import{z as i,x as l,o as E,c as s,q as A,j as t,D as e,d as o,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"有偏技术进步","description":"","frontmatter":{"title":"有偏技术进步","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/directed-technical-change.md","filePath":"econ/directed-technical-change.md","lastUpdated":1791413859000}'),p={name:"econ/directed-technical-change.md"};function d(c,a,h,m,_,u){const B=l("Mermaid");return E(),s("div",null,[a[2]||(a[2]=A('<h1 id="有偏技术进步" tabindex="-1">有偏技术进步 <a class="header-anchor" href="#有偏技术进步" aria-label="Permalink to &quot;有偏技术进步&quot;">​</a></h1><div class="epigraph"><p>技术不必是一个标量 $A$；研发朝哪一种要素、哪一种技能偏，本身由相对价格与市场规模决定。</p><footer>—— Acemoglu, Directed Technical Change, Review of Economic Studies 2002；对照技能偏向的经验讨论</footer></div><p><a href="/econ/ak-variety-schumpeter">上一课</a>把内生 \\(g\\) 分成 AK、种类与创造性破坏，对象仍是<strong>一个</strong>有效 \\(A\\) 如何被生产。本课的缺口是：创新可以有方向。劳动增进、资本增进、技能偏向，不是同一条残差。Acemoglu 把方向写成研发部门对相对利润的反应。制度下一课才问谁有激励去研发；本课先把「偏」从标量里拆出来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛把技术进步写成劳动增进型 \\(A\\)，好让稳态存在。内生增长课把 \\(\\dot{A}\\) 交给研发，仍常是一个 \\(A\\)。经验上技能溢价、资本份额、自动化可以各走各的。缺口不是再选 AK 还是熊彼特，而是：相对要素价格与市场大小如何<strong>引导</strong>研发朝哪种要素。弱要素可以因「贵」而吸引节约它的创新，也可以因市场太小而没人理——符号取决于替代弹性。</p><p><span class="marginnote">Hicks 已有引致创新的直觉。Acemoglu 的贡献是把价格效应与市场规模效应写进研发的相对利润，使偏可以内生反转。</span></p><p><span class="marginnote">「技能偏向型技术进步」翻译成日常话：新技术不是让所有人工效同比例提高，而是专门让受过高等教育的人更值钱——比如 Excel 代替算盘，受益的是会做分析的人，不是装卸工。它是一种「偏心」的技术进步，偏谁由研发利润决定，不由上天抽签。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两种要素（或技能）各有一条研发线。相对专利或相对 \\(A\\) 的增长，取决于相对利润：价格效应——哪种要素更贵，节约它更赚钱；市场规模效应——哪种要素用得多，改进它的市场更大。替代弹性大于一时，丰裕要素的市场足够大，技术进步朝它偏；小于一时，稀缺要素的价格效应主导。技能偏向：高等教育扩张可以<strong>提高</strong>技能溢价，若技术朝高技能偏得足够快。</p>',9)),(E(),t(n,null,{default:e(()=>[r(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REL%5B%22%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%E4%B8%8E%E5%B8%82%E5%9C%BA%E8%A7%84%E6%A8%A1%22%5D%20--%3E%20DIR%5B%22%E7%A0%94%E5%8F%91%E6%96%B9%E5%90%91%22%5D%0A%20%20DIR%20--%3E%20SBTC%5B%22%E6%8A%80%E8%83%BD%20%2F%20%E8%B5%84%E6%9C%AC%20%2F%20%E5%8A%B3%E5%8A%A8%E5%81%8F%E5%90%91%22%5D%0A%20%20SBTC%20--%3E%20SHARE%5B%22%E4%BB%BD%E9%A2%9D%E4%B8%8E%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20SHARE%20--%3E%20REL%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p>上一课的种类与质量阶梯仍然可用：偏的是「改进哪一类中间品或哪一级质量」，不是另起一套增长引擎。本课不估计跨国技能溢价回归。</p><h3 id="标量-抹掉的比较静态" tabindex="-1">标量 \\(A\\) 抹掉的比较静态 <a class="header-anchor" href="#标量-抹掉的比较静态" aria-label="Permalink to &quot;标量 $A$ 抹掉的比较静态&quot;">​</a></h3><p>加总 TFP 上升，可以是劳动节约（同样产出更少人），也可以是技能互补（高技能更值钱）。政策若只补贴「研发总量」，不声明偏向，可能加速替代刚想保护的那种劳动。错配课会说明楔子也表现为 \\(A\\)；本课的 \\(A\\) 向量仍是技术方向，不是管制。</p><h3 id="任务不是另一种标量" tabindex="-1">任务不是另一种标量 \\(A\\) <a class="header-anchor" href="#任务不是另一种标量" aria-label="Permalink to &quot;任务不是另一种标量 $A$&quot;">​</a></h3><p>把生产拆成任务后，自动化是资本或算法接手某些任务，而不是所有劳动的 \\(A\\) 一起升。偏向发生在任务边界上，加总份额可以非单调。</p><p>本课不展开任务核算。只要记住：要素偏向与任务替代是同一方向问题的两种写法，都不能退回一个 \\(g\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>相对供给冲击（移民、教育扩张、资本深化）改变相对价格，从而改变哪条研发线更赚。短期溢价由供给弹性定；长期溢价还取决于技术是否跟着偏。这与索洛外生 \\(g\\) 的差别是：长期要素份额可以内生漂，不必钉在生产函数的指数上。熊彼特式取代可以是「新机器取代旧技能」——创造性破坏有了要素对象。</p>',8)),(E(),t(n,null,{default:e(()=>[r(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E7%9B%B8%E5%AF%B9%E4%BE%9B%E7%BB%99%E5%86%B2%E5%87%BB%3A%20%E6%95%99%E8%82%B2%E6%89%A9%E5%BC%A0%22%5D%20--%3E%20PE%5B%22%E4%BB%B7%E6%A0%BC%E6%95%88%E5%BA%94%3A%20%E8%A6%81%E7%B4%A0%E5%8F%98%E4%BE%BF%E5%AE%9C%2C%20%E8%8A%82%E7%BA%A6%E5%AE%83%E5%9B%9E%E6%8A%A5%E9%99%8D%22%5D%0A%20%20SHOCK%20--%3E%20MS%5B%22%E5%B8%82%E5%9C%BA%E8%A7%84%E6%A8%A1%E6%95%88%E5%BA%94%3A%20%E7%94%A8%E5%BE%97%E5%A4%9A%E5%88%99%E6%94%B9%E8%BF%9B%E5%AE%83%E7%9A%84%E5%B8%82%E5%9C%BA%E5%A4%A7%22%5D%0A%20%20PE%20--%3E%20SC%5B%22%E6%9B%BF%E4%BB%A3%E5%BC%B9%E6%80%A7%E5%B0%8F%E4%BA%8E1%3A%20%E7%A8%80%E7%BC%BA%E8%A6%81%E7%B4%A0%E5%90%B8%E5%BC%95%E5%88%9B%E6%96%B0%22%5D%0A%20%20MS%20--%3E%20SB%5B%22%E6%9B%BF%E4%BB%A3%E5%BC%B9%E6%80%A7%E5%A4%A7%E4%BA%8E1%3A%20%E4%B8%B0%E8%A3%95%E8%A6%81%E7%B4%A0%E5%90%B8%E5%BC%95%E5%88%9B%E6%96%B0%22%5D%0A%20%20SB%20--%3E%20UP%5B%22%E6%8A%80%E6%9C%AF%E5%81%8F%E5%90%91%E6%8A%80%E8%83%BD%3A%20%E6%BA%A2%E4%BB%B7%E9%95%BF%E6%9C%9F%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<p><span class="marginnote">两种效应可以类比发明家用具：价格效应像节水马桶的发明——水费越贵，省水装置越有人买单；市场规模效应像智能手机 App——用户基数越大，为一个平台写应用越划算。哪种力量赢，取决于两种要素在生产里是「互相补位」还是「互相顶替」。</span></p><p>统一增长与制度会把方向接到人口与产权：谁拥有哪一种要素，谁推动哪一种创新。本课只关闭增长主干里「\\(A\\) 是标量」这一句。发展核算里的剩余 \\(A\\) 仍然看不出偏向；要看技能溢价、资本份额与任务数据。</p><p>要素份额若被写成 Cobb–Douglas 常数，有偏技术没有可见的落点。CES 或任务框架才让劳动增进与资本增进分叉。索洛为了稳态才把技术写成劳动增进；那是生长路径的技巧，不是经验上技术只增进人。把一切自动化都叫「TFP 上升」，会漏掉谁的边际产品被改写。</p><p><span class="marginnote">自动化是资本或任务偏向的当代说法。本课不把某一行业的机器人密度写成定律，只保留：方向是均衡对象，不是外生残差。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把有偏技术写成股市风格因子，也不做 CIP 检验。量化栏的因子模型不是这里的要素偏向。制度、殖民与地理的因果识别下一课才进；没有产权，研发利润那一项没有着落。</p><p>技能溢价的经验争论（教育扩张是否压低溢价、技术是否反向偏）不是本课要裁定的回归。主干只要：相对供给可以内生地拉技术方向，长期溢价不必按短期供给弹性去外推。把「提高教育」当成压技能溢价的充分政策，已经假定技术方向不变——上一课的种类与熊彼特也没有这个资格。</p><p><span class="marginnote">初学者容易以为大学扩招必然压低技能溢价——高学历的人多了嘛。Acemoglu 的结果可以反过来：若技术跟着劳动力结构朝技能偏（市场规模效应），扩招反而推高溢价。这意味着评估教育政策时不能假定技术方向是死的。</span></p><p>后课默认：谈到内生技术，要问朝哪一种要素偏，不能只报一个 \\(g\\)。下一课：同样的研发激励，为何有的地方被制度关掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AK/种类/熊彼特仍把技术当一条 \\(A\\)；本课把方向内生化。</li><li>价格效应与市场规模效应共同引导研发。</li><li>替代弹性决定丰裕要素是吸引创新还是被节约。</li><li>加总残差看不出偏向；份额与溢价才看见。</li><li>出处：Acemoglu, <em>RES</em> 2002；技能偏向的相对价格逻辑同一传统。</li></ul>',11))])}const T=i(p,[["render",d]]);export{g as __pageData,T as default};
